/* linux demo: a static-glibc Linux-ABI binary runs UNMODIFIED under
 * `andesim run --runtime linux` (USER_GUIDE 5.13). No andesim.specs, no
 * bare-metal runtime: the vlinux M-mode proxy kernel loads this ELF,
 * builds the Linux initial stack (argc/argv/envp/auxv) and serves the
 * syscalls over the HTIF window. The demo touches exactly what a real
 * app (llama.cpp) needs before its kernel -- argv via `--`, glibc
 * stdio, host-file I/O, a file-backed mmap, clock_gettime -- then a
 * marker'd scalar kernel is measured cycle-accurately under hybrid.
 *
 * Rules a vlinux app must follow (andesim ROADMAP_LINUX_RUNTIME.md):
 *  - stdio is not a tty here: glibc would fully buffer, so force
 *    unbuffered stdout or in-ROI prints sit in the buffer;
 *  - print INSIDE the ROI: on hybrid the run ends at the exit marker,
 *    nothing after andesim_ROI_end() is guaranteed to run;
 *  - leave via _exit(): glibc's exit() crashes in its own
 *    handler-list walk on this vendor toolchain (U4, documented gap).
 */
#include <andesim/ROI.h>
#include <fcntl.h>
#include <stdio.h>
#include <string.h>
#include <sys/mman.h>
#include <time.h>
#include <unistd.h>

#define FILE_BYTES 4096 /* data.bin: 16 x (0..255), byte sum 522240 */
#define N 16

static unsigned char filebuf[FILE_BYTES];

int main(int argc, char **argv)
{
  setvbuf(stdout, NULL, _IONBF, 0);

  if (argc != 2) {
    printf("[FAIL] argc=%d, want 2 (pass the data file: `-- <path>`)\n", argc);
    _exit(1);
  }
  printf("ARGS_OK argv1=%s\n", argv[1]);

  struct timespec t0, t1;
  if (clock_gettime(CLOCK_MONOTONIC, &t0) != 0 ||
      clock_gettime(CLOCK_MONOTONIC, &t1) != 0 ||
      t1.tv_sec < t0.tv_sec) {
    printf("[FAIL] clock_gettime\n");
    _exit(1);
  }
  printf("TIME_OK\n");

  FILE *f = fopen(argv[1], "rb");
  if (!f || fread(filebuf, 1, FILE_BYTES, f) != FILE_BYTES) {
    printf("[FAIL] fopen/fread %s\n", argv[1]);
    _exit(1);
  }
  fclose(f);
  unsigned long sum = 0;
  for (int i = 0; i < FILE_BYTES; ++i) sum += filebuf[i];
  printf("FILE_OK sum=%lu\n", sum);

  int fd = open(argv[1], O_RDONLY);
  void *map = fd < 0 ? MAP_FAILED
                     : mmap(NULL, FILE_BYTES, PROT_READ, MAP_PRIVATE, fd, 0);
  if (map == MAP_FAILED || memcmp(map, filebuf, FILE_BYTES) != 0) {
    printf("[FAIL] mmap readback\n");
    _exit(1);
  }
  close(fd);
  printf("MMAP_OK\n");

  /* The measured kernel: integer matvec over static arrays (anchored
   * through memory, per the ROI.h attribution contract), scalar rv64g
   * only -- one binary runs on every rv64 engine. check.sh derives the
   * expected checksum from these formulas; keep them in sync. */
  static long mat[N][N], vec[N], result[N];
  for (int i = 0; i < N; ++i) {
    vec[i] = i + 1;
    for (int j = 0; j < N; ++j) mat[i][j] = (i * N + j) % 7 + 1;
  }

  andesim_ROI_begin();
  for (int i = 0; i < N; ++i) {
    long acc = 0;
    for (int j = 0; j < N; ++j) acc += mat[i][j] * vec[j];
    result[i] = acc;
  }
  unsigned checksum = 0;
  for (int i = 0; i < N; ++i) checksum = checksum * 131 + (unsigned) result[i];
  printf("LINUX_OK checksum=%u\n", checksum);
  andesim_ROI_end();

  _exit(0);
}

